using Kerf.Engine.Exchange.Framework;
using Kerf.Engine.Exchange.Step.Data;
using Kerf.Engine.Geometry;
using Occt;

namespace Kerf.Engine.Exchange.Step.Visual.ReadWrite;

/// <summary>
/// Read &amp; Write Module for AnnotationOccurrence
/// </summary>
internal class RWCoordinatesList
{
    public RWCoordinatesList()
    {
    }

    public void ReadStep(StepReaderData data, int num, FrameworkCheck ach, CoordinatesList ent)
    {
        // Number of Parameter Control
        if (!data.CheckNbParams(num, 3, ach, "coordinate list"))
        {
            return;
        }

        // Inherited field : name
        TCollection_HAsciiString name = null;
        data.ReadString(num, 1, "name", ach, ref name);
        int nbP = 0;
        data.ReadInteger(num, 2, "number_points", ach, ref nbP);

        NCollection_HArray1<Xyz> points = null; // = new NCollection_HArray1<gp_XYZ>(1, nbP);
        int nsub2 = 0;
        if (data.ReadSubList(num, 3, "items", ach, ref nsub2))
        {
            int nb2 = data.NbParams(nsub2);
            if (nb2 == 0)
            {
                return;
            }
            points = new NCollection_HArray1<Xyz>(1, nb2);
            for (int i = 1; i <= nb2; i++)
            {
                Xyz xyz = new Xyz(0.0, 0.0, 0.0);
                int nsub3 = 0;
                if (data.ReadSubList(nsub2, i, "coordinates", ach, ref nsub3))
                {
                    int nb3 = data.NbParams(nsub3);
                    if (nb3 > 3)
                    {
                        ach.AddWarning("More than 3 coordinates, ignored");
                    }
                    int nbcoord = Min(nb3, 3);
                    for (int j = 1; j <= nbcoord; j++)
                    {
                        double val = 0.0;
                        if (data.ReadReal(nsub3, j, "coordinates", ach, ref val))
                        {
                            xyz.SetCoord(j, val);
                        }
                    }
                }
                points.SetValue(i, xyz);
            }
        }

        //--- Initialisation of the read entity ---

        ent.Init(name, points);
    }

    public void WriteStep(StepWriter sw, CoordinatesList ent)
    {
        // Inherited field : name
        sw.Send(ent.Name());

        // Own field : npoints
        sw.Send(ent.Points().Length());

        // Own field : position_coords
        sw.OpenSub();
        for (int i = 1; i <= ent.Points().Length(); i++)
        {
            sw.OpenSub();
            Xyz point = ent.Points().Value(i);
            sw.Send(point.X());
            sw.Send(point.Y());
            sw.Send(point.Z());
            sw.CloseSub();
        }
        sw.CloseSub();
    }
}
